CREATE TABLE projects(id INTEGER PRIMARY KEY,name VARCHAR(200) NOT NULL,status VARCHAR(30) DEFAULT 'PLANNING',start_date DATE,end_date DATE);
CREATE TABLE tasks(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL,parent_id INTEGER,name VARCHAR(200) NOT NULL,start_date DATE,end_date DATE,duration_days INTEGER,progress REAL DEFAULT 0,status VARCHAR(30) DEFAULT 'TODO',priority VARCHAR(20) DEFAULT 'MEDIUM');
CREATE TABLE resources(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL,name VARCHAR(200) NOT NULL,resource_type VARCHAR(30) NOT NULL,quantity REAL DEFAULT 1,unit VARCHAR(30) DEFAULT 'unit');
